) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_role_id uuid;
 v_exists boolean;
 v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
begin
